using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
namespace SoChiTieu;
public sealed class ChiTieu { public int MaCT {get;set;} public DateTime NgayChi {get;set;} public string NoiDung {get;set;}=""; public string LoaiChi {get;set;}=""; public decimal SoTien {get;set;} public string? GhiChu {get;set;} }
public sealed class QlChiTieuContext(string cs) : DbContext { public DbSet<ChiTieu> ChiTieu=>Set<ChiTieu>(); protected override void OnConfiguring(DbContextOptionsBuilder b)=>b.UseSqlServer(cs); protected override void OnModelCreating(ModelBuilder b){b.Entity<ChiTieu>(e=>{e.ToTable("ChiTieu");e.HasKey(x=>x.MaCT);e.Property(x=>x.NoiDung).HasMaxLength(100).IsRequired();e.Property(x=>x.LoaiChi).HasMaxLength(30).IsRequired();e.Property(x=>x.SoTien).HasColumnType("decimal(18,0)");e.Property(x=>x.GhiChu).HasMaxLength(200);});} }
public sealed class MainForm : Form
{
 readonly string cs; readonly ILogger log; readonly QlChiTieuContext db; readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false}; readonly DateTimePicker date=new(){Format=DateTimePickerFormat.Short}; readonly TextBox content=new(){Width=180}; readonly ComboBox category=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=120}; readonly NumericUpDown amount=new(){Maximum=100000000,Increment=1000,ThousandsSeparator=true}; readonly TextBox notes=new(){Width=180}; readonly TextBox search=new(){Width=150}; readonly ComboBox filter=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=120}; readonly DateTimePicker from=new(){Format=DateTimePickerFormat.Short}; readonly DateTimePicker to=new(){Format=DateTimePickerFormat.Short}; readonly Label total=new(){AutoSize=true,Font=new Font("Segoe UI",11,FontStyle.Bold)}; int id;
 public MainForm(string connection,ILogger<MainForm> logger){cs=connection;log=logger;db=new(cs);Text="Sổ chi tiêu cá nhân";Width=1100;Height=720;category.Items.AddRange(["Ăn uống","Đi lại","Học tập","Giải trí","Khác"]);filter.Items.Add("Tất cả");filter.Items.AddRange(["Ăn uống","Đi lại","Học tập","Giải trí","Khác"]);filter.SelectedIndex=0;from.Value=DateTime.Today.AddMonths(-1);to.Value=DateTime.Today;var fields=new FlowLayoutPanel{Dock=DockStyle.Top,Height=105,Padding=new Padding(8)};foreach(var (label,control) in new (string,Control)[]{("Ngày",date),("Nội dung",content),("Loại",category),("Số tiền",amount),("Ghi chú",notes)}){fields.Controls.Add(new Label{Text=label,AutoSize=true,Padding=new Padding(2,8,0,0)});fields.Controls.Add(control);}var actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=42};foreach(var (s,a) in new (string,Action)[]{("Thêm",Add),("Sửa",Edit),("Xóa",Delete),("Làm mới",Clear)}){var b=new Button{Text=s,AutoSize=true};b.Click+=(_,_)=>a();actions.Controls.Add(b);}var filters=new FlowLayoutPanel{Dock=DockStyle.Top,Height=42};filters.Controls.AddRange([new Label{Text="Tìm",AutoSize=true},search,new Label{Text="Loại",AutoSize=true},filter,new Label{Text="Từ",AutoSize=true},from,new Label{Text="Đến",AutoSize=true},to]);foreach(Control c in filters.Controls)if(c is not Label)c.TextChanged+=(_,_)=>LoadRows();search.TextChanged+=(_,_)=>LoadRows();filter.SelectedIndexChanged+=(_,_)=>LoadRows();from.ValueChanged+=(_,_)=>LoadRows();to.ValueChanged+=(_,_)=>LoadRows();grid.SelectionChanged+=(_,_)=>SelectRow();Controls.Add(grid);Controls.Add(total);Controls.Add(filters);Controls.Add(actions);Controls.Add(fields);Load+=(_,_)=>LoadRows();}
 void LoadRows(){try{var q=db.ChiTieu.AsNoTracking().AsQueryable();var term=search.Text.Trim();if(term!="")q=q.Where(x=>x.NoiDung.Contains(term));if(filter.SelectedIndex>0){var cat=filter.Text;q=q.Where(x=>x.LoaiChi==cat);}var a=from.Value.Date;var z=to.Value.Date;q=q.Where(x=>x.NgayChi>=a&&x.NgayChi<=z);var rows=q.OrderByDescending(x=>x.NgayChi).ToList();grid.DataSource=rows;total.Text=$"Tổng chi: {rows.Sum(x=>x.SoTien):N0} đ";}catch(Exception ex){log.LogError(ex,"Không đọc được dữ liệu chi tiêu");MessageBox.Show("Không thể truy cập dữ liệu. Hãy kiểm tra kết nối cơ sở dữ liệu.","Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void SelectRow(){if(grid.CurrentRow?.DataBoundItem is not ChiTieu x)return;id=x.MaCT;date.Value=x.NgayChi;content.Text=x.NoiDung;category.SelectedItem=x.LoaiChi;amount.Value=Math.Clamp(x.SoTien,amount.Minimum,amount.Maximum);notes.Text=x.GhiChu;}
 bool Valid(){if(string.IsNullOrWhiteSpace(content.Text)||amount.Value<=0||date.Value.Date>DateTime.Today){MessageBox.Show("Nhập nội dung, số tiền lớn hơn 0 và ngày không vượt quá hôm nay.");return false;}if(category.SelectedItem==null){MessageBox.Show("Hãy chọn loại chi.");return false;}return true;}
 ChiTieu Read()=>new(){NgayChi=date.Value.Date,NoiDung=content.Text.Trim(),LoaiChi=category.Text,SoTien=amount.Value,GhiChu=notes.Text.Trim()};
 void Add(){if(!Valid())return;try{var x=Read();db.Add(x);db.SaveChanges();log.LogInformation("Thêm chi tiêu MaCT={MaCT}",x.MaCT);Clear();LoadRows();}catch(Exception ex){log.LogError(ex,"Lỗi khi thêm chi tiêu");MessageBox.Show("Không thể lưu dữ liệu. Hãy thử lại.");}}
 void Edit(){if(id==0||!Valid())return;try{var x=db.ChiTieu.Find(id);if(x==null)return;var a=Read();x.NgayChi=a.NgayChi;x.NoiDung=a.NoiDung;x.LoaiChi=a.LoaiChi;x.SoTien=a.SoTien;x.GhiChu=a.GhiChu;db.SaveChanges();log.LogInformation("Sửa chi tiêu MaCT={MaCT}",id);LoadRows();}catch(Exception ex){log.LogError(ex,"Lỗi sửa chi tiêu MaCT={MaCT}",id);MessageBox.Show("Không thể cập nhật dữ liệu.");}}
 void Delete(){if(id==0||MessageBox.Show("Xóa khoản chi này?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{var x=db.ChiTieu.Find(id);if(x!=null){db.Remove(x);db.SaveChanges();log.LogInformation("Xóa chi tiêu MaCT={MaCT}",id);}Clear();LoadRows();}catch(Exception ex){log.LogError(ex,"Lỗi xóa chi tiêu MaCT={MaCT}",id);MessageBox.Show("Không thể xóa dữ liệu.");}}
 void Clear(){id=0;date.Value=DateTime.Today;content.Clear();category.SelectedIndex=-1;amount.Value=0;notes.Clear();grid.ClearSelection();}
}
